{
    "$schema": "http://json-schema.org/draft-07/schema#",
    "name": "sports_match_search",
    "description": "体育赛事赛程组合式搜索工具(sports_match_search)。当用户表达了搜索、查找、推荐体育赛事赛程的意图时触发，包括按球队/俱乐部(主队/客队)、运动员/球星、赛事名称、运动项目、比赛阶段、赛季、直播状态、轮次、赛事时间等维度筛选。不同字段间仅支持AND组合，不支持OR组合和NOT取反。支持多个精确匹配维度和1个范围维度(sport_time_range赛事时间区间)。",
    "type": "object",
    "properties": {
        "query": {
            "$ref": "#/definitions/QueryNode",
            "description": "搜索查询的根节点。可以是单个叶子节点，也可以是由 AND 组成的复合节点。仅支持AND逻辑，不支持OR/NOT。"
        }
    },
    "required": [
        "query"
    ],
    "additionalProperties": false,
    "definitions": {
        "QueryNode": {
            "description": "查询节点，支持两种形态：1) AND复合节点；2) 叶子条件节点(单个字段的匹配条件)。",
            "oneOf": [
                {
                    "$ref": "#/definitions/AndNode"
                },
                {
                    "$ref": "#/definitions/LeafNode"
                }
            ]
        },
        "AndNode": {
            "description": "AND逻辑组合节点。不同字段间仅用AND连接，同一字段values列表中多个值间也是AND连接(值内部含逗号则拆为OR子条件)。不支持OR组合和NOT取反。",
            "type": "object",
            "properties": {
                "and": {
                    "type": "array",
                    "items": {
                        "$ref": "#/definitions/QueryNode"
                    },
                    "minItems": 1,
                    "description": "AND逻辑：所有子节点条件必须同时满足。"
                }
            },
            "required": [
                "and"
            ],
            "additionalProperties": false
        },
        "LeafNode": {
            "description": "叶子条件节点，描述对某一搜索维度的具体匹配条件。可以是精确匹配或范围匹配。",
            "type": "object",
            "oneOf": [
                {
                    "$ref": "#/definitions/ExactFieldCondition"
                },
                {
                    "$ref": "#/definitions/RangeFieldCondition"
                }
            ]
        },
        "ExactFieldCondition": {
            "description": "精确匹配条件。value 为单值精确匹配；values 为多值数组时，列表中每个值用AND连接，若某个值内部含逗号则拆分为OR子条件。",
            "type": "object",
            "properties": {
                "field": {
                    "type": "string",
                    "enum": [
                        "sport_team",
                        "sport_team_home",
                        "sport_team_guest",
                        "sport_star",
                        "sport_game",
                        "sport_name",
                        "sport_competition_phase",
                        "sport_season",
                        "sport_time",
                        "live_state",
                        "round_offset"
                    ],
                    "description": "搜索维度字段名。sport_team:球队/俱乐部名称(主队/客队变体sport_team_home/sport_team_guest均映射到此字段)；sport_star:运动员/球星姓名；sport_game:具体赛事/比赛名称；sport_name:运动项目类型(如足球/篮球/网球等)；sport_competition_phase:比赛阶段(如小组赛/半决赛/决赛等)；sport_season:赛季(如2024-2025赛季)；sport_time:赛事时间，值为yyyyMMdd格式日期(如20240715)；live_state:直播状态(如1未开始/2进行中/3已结束/4回看等)；round_offset:轮次偏移(如第3轮等，不拼入query，单独作为URL参数处理)。"
                },
                "value": {
                    "type": "string",
                    "description": "单值精确匹配。若值内部含逗号，则按逗号拆分为OR子条件。"
                },
                "values": {
                    "type": "array",
                    "items": {
                        "type": "string"
                    },
                    "minItems": 1,
                    "description": "多值匹配。列表中每个值用AND连接，若某个值内部含逗号则拆分为OR子条件。"
                }
            },
            "required": [
                "field"
            ],
            "oneOf": [
                {
                    "required": [
                        "value"
                    ]
                },
                {
                    "required": [
                        "values"
                    ]
                }
            ],
            "additionalProperties": false
        },
        "RangeFieldCondition": {
            "description": "范围匹配条件。支持 sport_time_range(赛事时间区间) 范围字段，from/to 均为 yyyyMMdd HH:mm:ss 格式日期时间字符串，精确到秒，后续由系统转换为UTC秒级时间戳进行查询。搜索'比赛开始时间'处于 from(含) 和 to(含) 之间的赛程，from 和 to 可以一致。时间范围生成规则：1)用户输入具体时间但无范围时(如'明天下午1点的比赛')，以该时间点为起点，根据语义(之前/之后)往前或往后扩展1小时作为范围；2)用户输入具体日期但无范围时(如'6月17日之后的比赛')，以该日期为起点，根据语义(之前/之后)往前或往后扩展30天作为范围；3)特殊时段固定范围：凌晨00:00:00~06:00:00、早上04:00:00~12:00:00、上午08:00:00~12:00:00、中午12:00:00~14:00:00、下午12:00:00~18:00:00、傍晚17:00:00~19:00:00、晚上18:00:00~24:00:00。",
            "type": "object",
            "properties": {
                "field": {
                    "type": "string",
                    "enum": [
                        "sport_time_range"
                    ],
                    "description": "范围搜索维度字段名。sport_time_range:赛事时间区间，yyyyMMdd HH:mm:ss格式。"
                },
                "from": {
                    "type": "string",
                    "pattern": "^[0-9]{8} [0-9]{2}:[0-9]{2}:[0-9]{2}$",
                    "description": "起始时间(含)，格式 yyyyMMdd HH:mm:ss，精确到秒，如 20260127 06:00:00。"
                },
                "to": {
                    "type": "string",
                    "pattern": "^[0-9]{8} [0-9]{2}:[0-9]{2}:[0-9]{2}$",
                    "description": "结束时间(含)，格式 yyyyMMdd HH:mm:ss，精确到秒，如 20260127 07:00:00。"
                }
            },
            "required": [
                "field",
                "from",
                "to"
            ],
            "additionalProperties": false
        }
    }
}

