                        "sport_competition_phase",
                        "sport_season",
                        "sport_time",
                        "round_offset"
                    ],
                    "description": "搜索维度字段名。sport_team:球队/俱乐部名称(主队/客队变体sport_team_home/sport_team_guest均映射到此字段)；sport_star:运动员/球星姓名；sport_game:具体赛事/比赛名称；sport_name:运动项目类型(如足球/篮球/网球等)；sport_competition_phase:比赛阶段(如小组赛/半决赛/决赛等)；sport_season:赛季(如2024-2025赛季)；sport_time:赛事时间，值为yyyyMMdd格式日期(如20240715)；round_offset:轮次偏移(如第3轮等，不拼入query，单独作为URL参数处理)。注意：预约场景下 live_state 不作为搜索维度，由系统内部自动过滤可预约(未开始)的比赛。"
                },
                "value": {
                    "type": "string",
                    "description": "单值精确匹配。若值内部含逗号，则按逗号拆分为OR子条件。"
                },
                "values": {
                    "type": "array",
                    "items": {
                        "type": "string"
                    },
                    "minItems": 1,
                    "description": "多值匹配。列表中每个值用AND连接，若某个值内部含逗号则拆分为OR子条件。"
                }
            },
            "required": [
                "field"
            ],
            "oneOf": [
                {
                    "required": [
                        "value"
                    ]
                },
                {
                    "required": [
                        "values"
                    ]
                }
            ],
            "additionalProperties": false
        },
        "RangeFieldCondition": {
            "description": "范围匹配条件。支持 sport_time_range(赛事时间区间) 范围字段，from/to 均为 yyyyMMdd HH:mm:ss 格式日期时间字符串，精确到秒，后续由系统转换为UTC秒级时间戳进行查询。搜索'比赛开始时间'处于 from(含) 和 to(含) 之间的赛程，from 和 to 可以一致。时间范围生成规则：1)用户输入具体时间但无范围时(如'明天下午1点的比赛')，以该时间点为起点，根据语义(之前/之后)往前或往后扩展1小时作为范围；2)用户输入具体日期但无范围时(如'6月17日之后的比赛')，以该日期为起点，根据语义(之前/之后)往前或往后扩展30天作为范围；3)特殊时段固定范围：凌晨00:00:00~06:00:00、早上04:00:00~12:00:00、上午08:00:00~12:00:00、中午12:00:00~14:00:00、下午12:00:00~18:00:00、傍晚17:00:00~19:00:00、晚上18:00:00~24:00:00。",
            "type": "object",
            "properties": {
                "field": {
                    "type": "string",
                    "enum": [
                        "sport_time_range"
                    ],
                    "description": "范围搜索维度字段名。sport_time_range:赛事时间区间，yyyyMMdd HH:mm:ss格式。"
                },
                "from": {
                    "type": "string",
                    "pattern": "^[0-9]{8} [0-9]{2}:[0-9]{2}:[0-9]{2}$",
                    "description": "起始时间(含)，格式 yyyyMMdd HH:mm:ss，精确到秒，如 20260127 06:00:00。"
                },
                "to": {
                    "type": "string",
                    "pattern": "^[0-9]{8} [0-9]{2}:[0-9]{2}:[0-9]{2}$",
                    "description": "结束时间(含)，格式 yyyyMMdd HH:mm:ss，精确到秒，如 20260127 07:00:00。"
                }
            },
            "required": [
                "field",
                "from",
                "to"
            ],
            "additionalProperties": false
        }
    }
}

{
    "$schema": "http://json-schema.org/draft-07/schema#",
    "name": "sports_qa",
    "description": "体育问答(sports_qa)统一入口Schema。包含三部分：1) intent意图分类(枚举值)；2) query用户原始查询文本；3) search_slots搜索槽位信息(仅sports_match_forecast意图使用，用于赛程检索)。意图涵盖：单场比赛预测、赛事预测、单场比赛总结、赛事总结、体育基本信息查询、体育知识问答、体育人物查询、体育榜单模型意图。",
    "type": "object",
    "properties": {
        "intent": {
            "type": "string",
            "description": "用户意图分类。sports_match_forecast:单场比赛预测，预测某场具体比赛的胜负/比分等；sports_forecast:赛事预测，预测整个赛事的冠军/晋级等；sports_match_summary:单场比赛总结，总结某场已结束比赛的赛况；sports_summary:赛事总结，总结整个赛事的整体情况；sports_match_info_search:体育基本信息查询，查询赛程/比赛时间/对阵等基本信息；sports_chat_qa:体育知识问答，回答体育相关的知识性问题；sports_person_search:体育人物查询，查询运动员/教练等人物信息；sports_rank_llm_search:体育榜单模型意图，查询体育排行榜相关数据。",
            "enum": [
                "sports_match_forecast",
                "sports_forecast",
                "sports_match_summary",
                "sports_summary",
                "sports_match_info_search",
                "sports_chat_qa",
                "sports_person_search",
                "sports_rank_llm_search"
            ]
        },
        "query": {
            "type": "string",
            "description": "用户原始输入的查询文本。为用户的自然语言问题原文，用于意图理解、槽位提取和兜底问答。",
            "minLength": 1
        },
        "search_slots": {
            "$ref": "#/definitions/SearchSlots",
            "description": "搜索槽位信息，仅当intent为sports_match_forecast时使用。用于构建赛程检索query，通过AND/OR逻辑组合不同维度的搜索条件，定位到具体的比赛。"
        }
    },
    "required": [
        "intent",
        "query"
    ],
    "additionalProperties": false,
    "definitions": {
        "SearchSlots": {
            "description": "sports_match_forecast搜索槽位。包含一个query根节点，用于构建赛程检索的布尔查询表达式。不同字段间仅支持AND连接；同一字段多个值(values数组)间也是AND连接；若某个值内部含逗号，则按逗号拆分为OR子条件。round_offset不参与query拼接，单独作为URL参数传递。live_state由系统自动设置为未开始(liveState=1)，不作为用户可控搜索维度。",
            "type": "object",
            "properties": {
                "query": {
                    "$ref": "#/definitions/QueryNode",
                    "description": "搜索查询的根节点。可以是单个叶子节点，也可以是由AND组成的复合节点。仅支持AND逻辑，不支持OR组合节点和NOT取反。"
                },
                "round_offset": {
                    "type": "string",
                    "description": "轮次偏移(如'第3轮')。不参与query拼接，单独作为URL参数(roundOffset)传递给搜索API。"
                }
            },
            "required": [
                "query"
            ],
            "additionalProperties": false
        },
        "QueryNode": {
            "description": "查询节点，支持两种形态：1) AND复合节点(多个子条件AND连接)；2) 叶子条件节点(单个字段的匹配条件)。",
            "oneOf": [
                {
                    "$ref": "#/definitions/AndNode"
                },
                {
                    "$ref": "#/definitions/LeafNode"
                }
            ]
        },
        "AndNode": {
            "description": "AND逻辑组合节点。不同字段间仅用AND连接。拼接规则：每个子节点条件用括号包裹，子节点之间用AND连接。例如：(sport_team:皇马) AND (sport_name:足球)。不支持OR组合节点和NOT取反。",
            "type": "object",
            "properties": {
                "and": {
                    "type": "array",
                    "items": {
                        "$ref": "#/definitions/QueryNode"
                    },
                    "minItems": 1,
                    "description": "AND逻辑：所有子节点条件必须同时满足。拼接时每个子条件用()包裹，子条件间用AND连接。"
                }
            },
            "required": [
                "and"
            ],
            "additionalProperties": false
        },
        "LeafNode": {
            "description": "叶子条件节点，描述对某一搜索维度的具体匹配条件。可以是精确匹配或范围匹配。",
            "type": "object",
            "oneOf": [
                {
                    "$ref": "#/definitions/ExactFieldCondition"
                },
                {
                    "$ref": "#/definitions/RangeFieldCondition"
                }
            ]
        },
        "ExactFieldCondition": {
            "description": "精确匹配条件。value为单值精确匹配；values为多值数组。拼接规则：1) 单值value → (field:value)，如(sport_team:皇马)；2) 多值values → 每个值用AND连接，如(field:值1) AND (field:值2)；3) 若某个值内部含逗号，则按逗号拆分为OR子条件，如值为'皇马,巴萨' → ((field:皇马) OR (field:巴萨))。注意：此拼接逻辑对应buildsportsMatchQuery方法实现。",
            "type": "object",
            "properties": {
                "field": {
                    "type": "string",
                    "enum": [
                        "sport_team",
                        "team_name_home",
                        "team_name_guest",
                        "sport_star",
                        "sport_game",
                        "sport_name",
                        "sport_competition_phase",
                        "sport_season",
                        "sport_time"
                    ],
                    "description": "搜索维度字段名。sport_team:球队/俱乐部名称(如'皇马'、'湖人')；team_name_home:主队名称(如'曼联')；team_name_guest:客队名称(如'切尔西')；sport_star:运动员/球星姓名(如'梅西'、'詹姆斯')；sport_game:具体赛事/比赛名称(如'欧冠'、'NBA')；sport_name:运动项目类型(如'足球'、'篮球'、'网球')；sport_competition_phase:比赛阶段(如'小组赛'、'半决赛'、'决赛')；sport_season:赛季(如'2024-2025赛季')；sport_time:赛事时间，值为yyyyMMdd格式日期(如'20240715')。注意：live_state由系统自动设置(预测场景=未开始liveState=1)，不作为用户可控搜索维度。"
                },
                "value": {
                    "type": "string",
                    "description": "单值精确匹配。拼接为(field:value)格式。若值内部含逗号，则按逗号拆分为OR子条件，拼接为((field:值1) OR (field:值2))格式。"
                },
                "values": {
                    "type": "array",
                    "items": {
                        "type": "string"
                    },
                    "minItems": 1,
                    "description": "多值匹配。列表中每个值用AND连接，拼接为(field:值1) AND (field:值2)格式。若某个值内部含逗号，则该值按逗号拆分为OR子条件。"
                }
            },
            "required": [
                "field"
            ],
            "oneOf": [
                {
                    "required": [
                        "value"
                    ]
                },
                {
                    "required": [
                        "values"
                    ]
                }
            ],
            "additionalProperties": false
        },
        "RangeFieldCondition": {
            "description": "范围匹配条件。支持 sport_time_range(赛事时间区间) 范围字段，from/to 均为 yyyyMMdd HH:mm:ss 格式日期时间字符串，精确到秒，后续由系统转换为UTC秒级时间戳进行查询。搜索'比赛开始时间'处于 from(含) 和 to(含) 之间的赛程，from 和 to 可以一致。时间范围生成规则：1)用户输入具体时间但无范围时(如'明天下午1点的比赛')，以该时间点为起点，根据语义(之前/之后)往前或往后扩展1小时作为范围；2)用户输入具体日期但无范围时(如'6月17日之后的比赛')，以该日期为起点，根据语义(之前/之后)往前或往后扩展30天作为范围；3)特殊时段固定范围：凌晨00:00:00~06:00:00、早上04:00:00~12:00:00、上午08:00:00~12:00:00、中午12:00:00~14:00:00、下午12:00:00~18:00:00、傍晚17:00:00~19:00:00、晚上18:00:00~24:00:00。",
            "type": "object",
            "properties": {
                "field": {
                    "type": "string",
                    "enum": [
                        "sport_time_range"
                    ],
                    "description": "范围搜索维度字段名。sport_time_range:赛事时间区间，yyyyMMdd HH:mm:ss格式。"
                },
                "from": {
                    "type": "string",
                    "pattern": "^[0-9]{8} [0-9]{2}:[0-9]{2}:[0-9]{2}$",
                    "description": "起始时间(含)，格式 yyyyMMdd HH:mm:ss，精确到秒，如 20260127 06:00:00。"
                },
                "to": {
                    "type": "string",
                    "pattern": "^[0-9]{8} [0-9]{2}:[0-9]{2}:[0-9]{2}$",
                    "description": "结束时间(含)，格式 yyyyMMdd HH:mm:ss，精确到秒，如 20260127 07:00:00。"
                }
            },
            "required": [
                "field",
                "from",
                "to"
            ],
            "additionalProperties": false
        }
    }
}
